import { Schema } from "effect";
import { QuestionContent } from "./Question.ts";

/**
 * Names one Question of a Template. A Pulse copies the Question when it is added, so changing a
 * Template's text in code never changes a Pulse (GLOSSARY: Template). A new meaning needs a new key.
 */
export const TemplateQuestionKey = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[a-z][a-z0-9-]{0,39}$/)),
  Schema.brand("TemplateQuestionKey"),
);
export type TemplateQuestionKey = typeof TemplateQuestionKey.Type;

export const TemplateQuestion = Schema.Struct({
  key: TemplateQuestionKey,
  ...QuestionContent.fields,
});
export type TemplateQuestion = typeof TemplateQuestion.Type;

export interface Template {
  readonly name: string;
  readonly questions: ReadonlyArray<TemplateQuestion>;
}

const key = (value: string) => TemplateQuestionKey.make(value);

/**
 * The weekly team health Template, the only one in Release 1. Its Questions are grouped by
 * Dimension; a new Pulse starts with all of them, in this order. The first is a rating, so the
 * Invitation email can offer one-tap answers (ADR 0007).
 */
export const WEEKLY_TEAM_HEALTH: Template = {
  name: "Weekly team health",
  questions: [
    {
      key: key("workload-manageable"),
      dimension: "workload",
      text: "How manageable was your workload this week?",
      type: { _tag: "Rating", lowLabel: "Not manageable", highLabel: "Very manageable", comment: true },
    },
    {
      key: key("safe-to-speak-up"),
      dimension: "psychologicalSafety",
      text: "How safe did you feel raising concerns or mistakes in the team?",
      type: { _tag: "Rating", lowLabel: "Not safe", highLabel: "Completely safe", comment: true },
    },
    {
      key: key("priorities-clear"),
      dimension: "clarity",
      text: "How clear were your priorities this week?",
      type: { _tag: "Rating", lowLabel: "Very unclear", highLabel: "Very clear", comment: false },
    },
    {
      key: key("work-recognised"),
      dimension: "recognition",
      text: "How recognised did you feel for your work this week?",
      type: { _tag: "Rating", lowLabel: "Not at all", highLabel: "Very much", comment: false },
    },
    {
      key: key("biggest-obstacle"),
      dimension: "workload",
      text: "What slowed you down most this week?",
      type: {
        _tag: "SingleChoice",
        options: [
          "Unclear goals",
          "Waiting on others",
          "Interruptions",
          "Too much work",
          "Nothing in particular",
        ],
      },
    },
    {
      key: key("shout-out"),
      dimension: "recognition",
      text: "What went well this week?",
      type: { _tag: "LongText" },
    },
  ],
};

export const templateQuestion = (questionKey: TemplateQuestionKey): TemplateQuestion | undefined =>
  WEEKLY_TEAM_HEALTH.questions.find((question) => question.key === questionKey);
/**
 * Rule-based comment redaction (ADR 0001, ADR 0009).
 * Runs at store time in the Submission Worker so that no raw comment is ever kept at rest.
 */

export type RosterItem =
  | string
  | {
      readonly name?: string | null | undefined;
      readonly firstName?: string | null | undefined;
      readonly lastName?: string | null | undefined;
      readonly email?: string | null | undefined;
    };

export type Roster = ReadonlyArray<RosterItem>;

const URL_PATTERN = /(?:https?:\/\/|www\.)[^\s<>"'()[\]{},]+(?<![.,!?:;])/gi;
const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/gi;
const HANDLE_PATTERN = /(?:^|(?<=[^\w@]))@[A-Za-z0-9_]+(?=[^\w]|$)/g;

// 7+ digits with common separators (+, -, ., space, parentheses, slash)
const PHONE_PATTERN =
  /(?:^|(?<=[^\w+]))((?:\+\d{1,4}[-.\s]?)?(?:\(?\d{2,5}\)?[-.\s]?)(?:\d{2,5}[-.\s]?){1,4}\d{2,5})(?=[^\w]|$)/g;

const stripDiacritics = (text: string): string =>
  text
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();

interface CandidateName {
  readonly norm: string;
  readonly words: ReadonlyArray<string>;
  readonly wordCount: number;
}

const extractCandidateNames = (roster: Roster): ReadonlyArray<CandidateName> => {
  const rawNames = new Set<string>();

  for (const item of roster) {
    if (typeof item === "string") {
      const trimmed = item.trim();
      if (trimmed.includes("@")) {
        const localPart = trimmed.split("@")[0] ?? "";
        if (localPart) {
          rawNames.add(localPart);
          for (const sub of localPart.split(/[._-]/)) {
            if (sub) rawNames.add(sub);
          }
        }
      } else {
        rawNames.add(trimmed);
        for (const sub of trimmed.split(/\s+/)) {
          if (sub) rawNames.add(sub);
        }
      }
    } else if (item && typeof item === "object") {
      if (item.name) {
        rawNames.add(item.name.trim());
        for (const sub of item.name.trim().split(/\s+/)) {
          if (sub) rawNames.add(sub);
        }
      }
      if (item.firstName) rawNames.add(item.firstName.trim());
      if (item.lastName) rawNames.add(item.lastName.trim());
      if (item.email) {
        const localPart = item.email.trim().split("@")[0] ?? "";
        if (localPart) {
          rawNames.add(localPart);
          for (const sub of localPart.split(/[._-]/)) {
            if (sub) rawNames.add(sub);
          }
        }
      }
    }
  }

  const seen = new Set<string>();
  const candidates: Array<CandidateName> = [];

  for (const name of rawNames) {
    const norm = stripDiacritics(name.trim());
    if (norm.length < 2 || seen.has(norm)) continue;
    seen.add(norm);

    const words = norm.split(/\s+/).filter((w) => w.length > 0);
    if (words.length > 0) {
      candidates.push({
        norm,
        words,
        wordCount: words.length,
      });
    }
  }

  // Greedy match: multi-word names first, then longer names
  return candidates.sort((a, b) => b.wordCount - a.wordCount || b.norm.length - a.norm.length);
};

const redactNames = (text: string, candidates: ReadonlyArray<CandidateName>): string => {
  if (candidates.length === 0) return text;

  const segmenter = new Intl.Segmenter("en", { granularity: "word" });
  const segments = [...segmenter.segment(text)];

  let result = "";
  let i = 0;

  while (i < segments.length) {
    const seg = segments[i];
    if (seg === undefined) break;

    if (!seg.isWordLike) {
      result += seg.segment;
      i++;
      continue;
    }

    let matched = false;

    for (const candidate of candidates) {
      if (candidate.wordCount > 1) {
        // Multi-word name lookahead
        let wordIdx = i;
        let matchedCount = 0;
        let spanEnd = i;
        const collectedWords: Array<string> = [];
        let possessiveSuffix = "";

        while (wordIdx < segments.length && matchedCount < candidate.wordCount) {
          const nextSeg = segments[wordIdx];
          if (nextSeg === undefined) break;
          if (nextSeg.isWordLike) {
            let segWord = nextSeg.segment;
            if (matchedCount === candidate.wordCount - 1) {
              if (segWord.endsWith("'s") || segWord.endsWith("’s")) {
                possessiveSuffix = segWord.slice(-2);
                segWord = segWord.slice(0, -2);
              }
            }
            collectedWords.push(stripDiacritics(segWord));
            matchedCount++;
            spanEnd = wordIdx;
          }
          wordIdx++;
        }

        if (matchedCount === candidate.wordCount && collectedWords.join(" ") === candidate.words.join(" ")) {
          result += "[name]" + possessiveSuffix;
          i = spanEnd + 1;
          matched = true;
          break;
        }
      } else {
        // Single word candidate
        let word = seg.segment;
        let suffix = "";
        if (word.endsWith("'s") || word.endsWith("’s")) {
          suffix = word.slice(-2);
          word = word.slice(0, -2);
        }

        if (stripDiacritics(word) === candidate.norm) {
          result += "[name]" + suffix;
          i++;
          matched = true;
          break;
        }
      }
    }

    if (!matched) {
      result += seg.segment;
      i++;
    }
  }

  return result;
};

/**
 * Pure function to redact identifying info (URLs, emails, handles, phone numbers, and roster names)
 * from comments according to ADR 0001 and ADR 0009.
 */
export const redact = (text: string, roster: Roster): string => {
  if (!text) return "";

  // 1,000-character limit counted after Unicode normalization
  const normalized = text.normalize("NFC");
  const bounded = normalized.length > 1000 ? normalized.slice(0, 1000) : normalized;

  // 1. Redact URLs
  let result = bounded.replace(URL_PATTERN, "[link]");

  // 2. Redact Email addresses
  result = result.replace(EMAIL_PATTERN, "[email]");

  // 3. Redact @handles
  result = result.replace(HANDLE_PATTERN, "[handle]");

  // 4. Redact Phone numbers (7+ digits with separators, keeping plain numbers)
  result = result.replace(PHONE_PATTERN, (match, p1: string) => {
    const digits = (p1.match(/\d/g) ?? []).length;
    const hasSeparators = /[-.\s()+]/.test(p1);
    if (digits >= 7 && hasSeparators) {
      return match.replace(p1, "[phone]");
    }
    return match;
  });

  // 5. Redact roster names
  const candidates = extractCandidateNames(roster);
  result = redactNames(result, candidates);

  return result;
};

import { describe, expect, it } from "vitest";
import { redact, type Roster } from "./Redaction.ts";

describe("redact", () => {
  const roster: Roster = [
    "Anna",
    "Mary Ann Lee",
    "will",
    "may",
    { name: "John Doe", email: "john.doe@example.com" },
    { firstName: "Ada", lastName: "Lovelace", email: "ada@example.com" },
  ];

  it("redacts case and accents: anna, ANNA, Ánna", () => {
    expect(redact("Talked to anna yesterday.", roster)).toBe("Talked to [name] yesterday.");
    expect(redact("Talked to ANNA yesterday.", roster)).toBe("Talked to [name] yesterday.");
    expect(redact("Talked to Ánna yesterday.", roster)).toBe("Talked to [name] yesterday.");
  });

  it("redacts possessives: Anna's, Anna’s", () => {
    expect(redact("That was Anna's presentation.", roster)).toBe("That was [name]'s presentation.");
    expect(redact("That was Anna’s presentation.", roster)).toBe("That was [name]’s presentation.");
  });

  it("redacts multi-word names: Mary Ann Lee", () => {
    expect(redact("Mary Ann Lee led the meeting.", roster)).toBe("[name] led the meeting.");
    expect(redact("Mary Ann Lee's project was great.", roster)).toBe("[name]'s project was great.");
  });

  it("redacts ordinary words that are roster names: will, may", () => {
    expect(redact("This will happen soon.", roster)).toBe("This [name] happen soon.");
    expect(redact("We may need more time.", roster)).toBe("We [name] need more time.");
  });

  it("redacts an email address, 5 phone formats, an @handle, and a URL containing a name", () => {
    // 1. Email address
    expect(redact("Contact me at someone@domain.com for info.", roster)).toBe(
      "Contact me at [email] for info.",
    );

    // 2. Five phone formats
    expect(redact("Call +1 (555) 234-5678 today.", roster)).toBe("Call [phone] today.");
    expect(redact("Call 555-234-5678 today.", roster)).toBe("Call [phone] today.");
    expect(redact("Call (555) 234-5678 today.", roster)).toBe("Call [phone] today.");
    expect(redact("Call 555.234.5678 today.", roster)).toBe("Call [phone] today.");
    expect(redact("Call +49 30 1234567 today.", roster)).toBe("Call [phone] today.");

    // Plain numbers stay
    expect(redact("We served 1000000 customers in 2026 with 50000 items.", roster)).toBe(
      "We served 1000000 customers in 2026 with 50000 items.",
    );

    // 3. @handle
    expect(redact("Ping @chrisdoc or @anna on chat.", roster)).toBe("Ping [handle] or [handle] on chat.");

    // 4. URL containing a name
    expect(redact("See https://example.com/anna/profile for details.", roster)).toBe(
      "See [link] for details.",
    );
  });

  it("redacts names glued to punctuation: (Anna), Anna,, Anna!", () => {
    expect(redact("Great idea (Anna)!", roster)).toBe("Great idea ([name])!");
    expect(redact("Thanks, Anna, for your help.", roster)).toBe("Thanks, [name], for your help.");
    expect(redact("Anna! What a surprise.", roster)).toBe("[name]! What a surprise.");
  });

  it("keeps 'Ann' inside 'annual'", () => {
    expect(redact("Our annual planning is next week.", roster)).toBe("Our annual planning is next week.");
  });

  it("extracts and redacts names from object roster items and email local parts", () => {
    expect(redact("Reviewed by John Doe.", roster)).toBe("Reviewed by [name].");
    expect(redact("Reviewed by John.", roster)).toBe("Reviewed by [name].");
    expect(redact("Sent by ada.", roster)).toBe("Sent by [name].");
  });

  it("ignores names shorter than 2 characters", () => {
    const singleLetterRoster: Roster = ["A", "x", "Bob"];
    expect(redact("A quick test with Bob and x.", singleLetterRoster)).toBe(
      "A quick test with [name] and x.",
    );
  });

  it("enforces 1,000-character limit after Unicode normalisation", () => {
    const longText = "a".repeat(1050) + " Anna";
    const result = redact(longText, roster);
    expect(result.length).toBeLessThanOrEqual(1000);
    expect(result).not.toContain("Anna");
  });

  it("property test: no roster name survives in random sentences", () => {
    const names = ["Alice", "Bob", "Charlie", "Daphne", "Edward"];
    const testRoster: Roster = names;

    const words = [
      "the",
      "quick",
      "brown",
      "fox",
      "jumped",
      "over",
      "lazy",
      "dog",
      "meeting",
      "today",
      "review",
      "shared",
      "code",
      "project",
    ];

    // Seeded-style pseudo random generator
    let seed = 42;
    const rnd = () => {
      seed = (seed * 9301 + 49297) % 233280;
      return seed / 233280;
    };

    for (let i = 0; i < 50; i++) {
      const sentenceLength = Math.floor(rnd() * 15) + 5;
      const sentenceWords: Array<string> = [];

      for (let j = 0; j < sentenceLength; j++) {
        if (rnd() < 0.3) {
          // Insert a roster name with possible punctuation or possessive
          const name = names[Math.floor(rnd() * names.length)]!;
          const variant = rnd();
          if (variant < 0.25) sentenceWords.push(name.toLowerCase());
          else if (variant < 0.5) sentenceWords.push(name.toUpperCase());
          else if (variant < 0.75) sentenceWords.push(`${name}'s`);
          else sentenceWords.push(`(${name})`);
        } else {
          sentenceWords.push(words[Math.floor(rnd() * words.length)]!);
        }
      }

      const sentence = sentenceWords.join(" ") + ".";
      const redacted = redact(sentence, testRoster);

      // Verify no whole word in redacted text matches any of the roster names
      const segmenter = new Intl.Segmenter("en", { granularity: "word" });
      for (const seg of segmenter.segment(redacted)) {
        if (seg.isWordLike) {
          let word = seg.segment.toLowerCase();
          if (word.endsWith("'s") || word.endsWith("’s")) word = word.slice(0, -2);
          for (const name of names) {
            expect(word).not.toBe(name.toLowerCase());
          }
        }
      }
    }
  });
});
